export const portraitMaxLimitBreak = 5;

export function getPortraitDescription(p: Portrait, enchantmentLevel = portraitMaxLimitBreak): string {
    return passiveBase[p.passiveSkill1 * 100 + 1 + enchantmentLevel].description.replaceAll("<br>", "\n")
}

function splitBattleSkill(description: string) {
    const lowDesc = description.toLowerCase()
    if (!lowDesc.includes("dmg dealt")) return ""
    if (lowDesc.includes("battle")) return "_BATTLE"
    if (lowDesc.includes("special")) return "_SPECIAL"
    if (lowDesc.includes("follow")) return "_FUA"
    return ""
}

export function getPortraitEffectType(p: Portrait, enchantmentLevel = portraitMaxLimitBreak): Record<string, number> {
    const details = Object.values(passiveDetails).filter((v: any) => v.passiveSkillMstId === p.passiveSkill1 * 100 + 1 + enchantmentLevel)
    const effects = Object.fromEntries(details.map(b => [`${b.abilityEffectType}${splitBattleSkill(b.description)}${b.element ? "_" + elementMap[b.element].toUpperCase() : ""}`, b.value1]))
    return Object.keys(effects).length ? effects : { "Unknown": 0 }
}

export const ROLE_COEFFICIENTS: Record<KiokuRole, { hp: number; atk: number; def: number }> = {
    [KiokuRole.Attacker]: { hp: 950, atk: 1100, def: 950 },
    [KiokuRole.Breaker]: { hp: 1000, atk: 1000, def: 1000 },
    [KiokuRole.Healer]: { hp: 1000, atk: 1000, def: 1000 },
    [KiokuRole.Buffer]: { hp: 1000, atk: 1000, def: 1000 },
    [KiokuRole.Debuffer]: { hp: 1000, atk: 1000, def: 1000 },
    [KiokuRole.Defender]: { hp: 1050, atk: 800, def: 1150 },
};

export function getStatPwr(atk: number, def: number, hp: number, role: KiokuRole = KiokuRole.Buffer): number {
    const roleCoeff = ROLE_COEFFICIENTS[role];
    const hpTerm = (100 / 1000) * hp * (roleCoeff.hp / 1000);
    const atkTerm = (300 / 1000) * atk * (roleCoeff.atk / 1000);
    const defTerm = (300 / 1000) * def * (roleCoeff.def / 1000);
    return Math.floor(hpTerm + atkTerm + defTerm);
}

export function getPortraitPwr(p: Portrait, level: number, role: KiokuRole = KiokuRole.Buffer): number {
    const stats = p.stats?.[level];
    if (!stats) return 0;
    return getStatPwr(stats.atk, stats.def, stats.hp, role);
}

export function getPortraitMaxPwr(p: Portrait, level: number): number {
    return Math.max(
        ...(Object.keys(ROLE_COEFFICIENTS) as KiokuRole[]).map(role => getPortraitPwr(p, level, role))
    );
}

export function getPortraitPwrTitle(p: Portrait, level: number): string {
    return (Object.keys(ROLE_COEFFICIENTS) as KiokuRole[])
        .map(role => ({ role, value: getPortraitPwr(p, level, role) }))
        .sort((a, b) => b.value - a.value)
        .map(({ role, value }) => `${role}: ${value.toLocaleString()}`)
        .join("\n");
}


