export interface MagicLevelBreakpoint {
    minKiokuLvl: number
    maxMagicLvl: number
}

export const magicLevelBreakpoints: MagicLevelBreakpoint[] = [
    { minKiokuLvl: 1, maxMagicLvl: 30 },
    { minKiokuLvl: 30, maxMagicLvl: 60 },
    { minKiokuLvl: 60, maxMagicLvl: 90 },
    { minKiokuLvl: 90, maxMagicLvl: 120 },
    { minKiokuLvl: 101, maxMagicLvl: 125 },
    { minKiokuLvl: 110, maxMagicLvl: 130 },
    { minKiokuLvl: 136, maxMagicLvl: 135 },
    { minKiokuLvl: 146, maxMagicLvl: 140 },
]

export function getMaxMagicLevelForKiokuLevel(kiokuLvl: number): number {
    let cap = magicLevelBreakpoints[0].maxMagicLvl
    for (const bp of magicLevelBreakpoints) {
        if (kiokuLvl < bp.minKiokuLvl) break
        cap = bp.maxMagicLvl
    }
    return Math.min(cap, KiokuConstants.maxMagicLvl)
}

export function getMaxKiokuLevelForPlayerLevel(playerLevel: number): number {
    return Math.min(Math.max(playerLevel || 0, KiokuConstants.minKiokuLvl), KiokuConstants.maxKiokuLvl)
}

export function getMaxSpecialLevelForAscension(ascension: number): number {
    if (ascension < 3) return 4
    if (ascension < 5) return 7
    return KiokuConstants.maxSpecialLvl
}

export function withMaxLevelsForPlayerLevel<T extends { kiokuLvl: number; magicLvl: number; heartphialLvl: number; specialLvl: number; ascension: number }>(
    char: T,
    playerLevel: number
): T {
    const kiokuLvl = getMaxKiokuLevelForPlayerLevel(playerLevel)
    const magicLvl = getMaxMagicLevelForKiokuLevel(kiokuLvl)
    const heartphialLvl = KiokuConstants.maxHeartphialLvl
    const specialLvl = getMaxSpecialLevelForAscension(char.ascension)
    return { ...char, kiokuLvl, magicLvl, heartphialLvl, specialLvl }
}

